window.VO = [{"id":"n01","text":"You're the guard, and what you write in this register sends a man to jail.","at":0.24,"t0":0.12,"t1":3.975},{"id":"n02","text":"Flats on this street are being robbed, so ask this man his name.","at":8.45,"t0":4.225,"t1":7.785},{"id":"a01","text":"Ravi, sir.","at":15.97,"t0":7.985,"t1":8.92},{"id":"n03","text":"Write it down, and ask which flat.","at":18.14,"t0":9.07,"t1":10.875},{"id":"b01","text":"Three zero two.","at":22.05,"t0":11.025,"t1":12.22},{"id":"n04","text":"Write that too, and check his parcel.","at":25.14,"t0":12.57,"t1":14.695},{"id":"c01","text":"Here it is, sir.","at":29.69,"t0":14.845,"t1":15.9},{"id":"n05","text":"Does it match your register?","at":32.2,"t0":16.1,"t1":17.51},{"id":"n06","text":"Good catch.","at":37.22,"t0":18.61,"t1":19.48},{"id":"d01","text":"Sorry, sir. I'll call the customer.","at":39.46,"t0":19.73,"t1":21.795},{"id":"n07","text":"So nobody got past you.","at":44.29,"t0":22.145,"t1":23.62},{"id":"n08","text":"Then who robbed flat three zero two?","at":47.64,"t0":23.82,"t1":25.725},{"id":"n09","text":"Police have four men in that jacket, but your register says one came, so point him out.","at":51.85,"t0":25.925,"t1":30.97},{"id":"n10","text":"He goes to jail, and the other three go home.","at":62.34,"t0":31.17,"t1":33.69},{"id":"n11","text":"Which one? You looked right at him.","at":67.78,"t0":33.89,"t1":35.715},{"id":"n12","text":"You're right. He was at your gate, and so were the other three.","at":74.93,"t0":37.465,"t1":40.52},{"id":"n13","text":"Every time you looked down, one walked in and the next stepped up, and you carried on.","at":82.54,"t0":41.27,"t1":45.565},{"id":"n14","text":"So three of them go home. Four, if you said none.","at":91.73,"t0":45.865,"t1":48.675},{"id":"n15","text":"In a real experiment, a woman who missed a swap like this said she'd just seen a construction worker.","at":98.15,"t0":49.075,"t1":54.46},{"id":"n16","text":"And these four aren't even delivery men. You just saw a jacket.","at":109.52,"t0":54.76,"t1":58.22},{"id":"n17","text":"Your register says Ravi.","at":117.34,"t0":58.67,"t1":60.12},{"id":"n18","text":"So which one said Ravi?","at":120.64,"t0":60.32,"t1":61.765}];
